using System.Collections.Concurrent;

namespace ResearchAgent;

/// <summary>
/// Thread-safe store for research notes collected by the agent.
/// </summary>
public sealed class NoteStore
{
    private readonly ConcurrentBag<Note> _notes = [];

    public void Add(string title, string content, string source)
    {
        _notes.Add(new Note(title, content, source, DateTimeOffset.UtcNow));
    }

    public IReadOnlyList<Note> GetAll() => [.. _notes];

    public override string ToString()
    {
        if (_notes.IsEmpty) return "No notes recorded yet.";

        return string.Join(Environment.NewLine + Environment.NewLine,
            _notes.Select((n, i) =>
                $"[{i + 1}] {n.Title}\n    Source: {n.Source}\n    {n.Content}"));
    }
}

public sealed record Note(string Title, string Content, string Source, DateTimeOffset Timestamp);

using System.ComponentModel;
using System.Net;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Tools exposed to the AI agent for web searching and note-taking.
/// </summary>
public sealed class ResearchTools(NoteStore noteStore, ILogger<ResearchTools> logger)
{
    private static readonly HttpClient HttpClient = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Search the web for information on a topic. Returns a list of result titles, snippets, and URLs.")]
    public async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        logger.LogInformation("🔍 Searching: {Query}", query);

        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await HttpClient.GetStringAsync(url);
            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new List<string>();

            // Abstract / instant answer
            var abstractText = root.GetProperty("Abstract").GetString();
            var abstractUrl = root.GetProperty("AbstractURL").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                results.Add($"**Instant Answer**\n{abstractText}\nSource: {abstractUrl}");
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(8))
                {
                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    var link = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        results.Add($"• {text}\n  URL: {link}");
                    }
                }
            }

            if (results.Count == 0)
            {
                return $"No results found for '{query}'. Try rephrasing the query.";
            }

            return string.Join("\n\n", results);
        }
        catch (Exception ex)
        {
            logger.LogWarning(ex, "Search failed for query: {Query}", query);
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note with a title, content summary, and source URL. Use this to record important findings.")]
    public string SaveNote(
        [Description("Short title for the note")] string title,
        [Description("Content or summary of the finding")] string content,
        [Description("Source URL or reference")] string source)
    {
        noteStore.Add(title, content, source);
        logger.LogInformation("📝 Note saved: {Title}", title);
        return $"Note '{title}' saved successfully. Total notes: {noteStore.GetAll().Count}";
    }

    [Description("Retrieve all saved research notes collected so far.")]
    public string GetNotes()
    {
        var notes = noteStore.ToString();
        logger.LogInformation("📋 Retrieved {Count} notes", noteStore.GetAll().Count);
        return notes;
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Agents.AI;

namespace ResearchAgent;

/// <summary>
/// Hosted service that prompts the user for a topic and runs the research agent.
/// </summary>
public sealed class ResearchHostedService(
    IChatClient chatClient,
    ResearchTools tools,
    NoteStore noteStore,
    IHostApplicationLifetime lifetime,
    ILogger<ResearchHostedService> logger) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        Console.WriteLine("╔══════════════════════════════════╗");
        Console.WriteLine("║     🔬 AI Research Agent         ║");
        Console.WriteLine("╚══════════════════════════════════╝");
        Console.WriteLine();

        Console.Write("Enter a research topic (or press Enter for default): ");
        var topic = Console.ReadLine()?.Trim();
        if (string.IsNullOrWhiteSpace(topic))
        {
            topic = "the impact of large language models on software engineering";
        }

        Console.WriteLine();
        Console.WriteLine($"📚 Researching: {topic}");
        Console.WriteLine(new string('─', 50));

        try
        {
            await RunResearchAgent(topic, stoppingToken);
        }
        catch (Exception ex)
        {
            logger.LogError(ex, "Research agent failed");
            Console.WriteLine($"\n❌ Error: {ex.Message}");
        }
        finally
        {
            lifetime.StopApplication();
        }
    }

    private async Task RunResearchAgent(string topic, CancellationToken ct)
    {
        var agent = new ChatClientAgent(chatClient,
            $"""
            You are a research assistant. Your job is to thoroughly research a given topic
            using the search tool and save important findings as notes.

            Follow this process:
            1. Search for the topic using different query angles (at least 3 searches).
            2. For each useful result, save a note with a clear title, concise summary, and the source.
            3. After gathering enough information, retrieve all your notes.
            4. Finally, write a comprehensive summary of your findings organized by theme.

            Be thorough but concise. Focus on factual, well-sourced information.
            """);

        var options = new AgentInvokeOptions
        {
            MaximumIterations = 15,
            Tools = [
                AIFunctionFactory.Create(tools.SearchWeb),
                AIFunctionFactory.Create(tools.SaveNote),
                AIFunctionFactory.Create(tools.GetNotes),
            ],
        };

        var history = new List<ChatMessage>
        {
            new(ChatRole.User,
                $"Research the following topic and provide a comprehensive summary: {topic}"),
        };

        Console.WriteLine();
        Console.WriteLine("🤖 Agent is working...");
        Console.WriteLine();

        await foreach (var response in agent.InvokeStreamingAsync(history, options, ct))
        {
            if (response.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(response.Text))
            {
                Console.Write(response.Text);
            }
        }

        Console.WriteLine();
        Console.WriteLine();
        Console.WriteLine(new string('═', 50));
        Console.WriteLine($"📝 Total notes collected: {noteStore.GetAll().Count}");
        Console.WriteLine(new string('═', 50));
    }
}

