using System.ComponentModel;
using System.Net;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Tools exposed to the AI agent for web searching and note-taking.
/// </summary>
public sealed class ResearchTools(NoteStore noteStore, ILogger<ResearchTools> logger)
{
    private static readonly HttpClient HttpClient = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Search the web for information on a topic. Returns a list of result titles, snippets, and URLs.")]
    public async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        logger.LogInformation("🔍 Searching: {Query}", query);

        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await HttpClient.GetStringAsync(url);
            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new List<string>();

            // Abstract / instant answer
            var abstractText = root.GetProperty("Abstract").GetString();
            var abstractUrl = root.GetProperty("AbstractURL").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                results.Add($"**Instant Answer**\n{abstractText}\nSource: {abstractUrl}");
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(8))
                {
                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    var link = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        results.Add($"• {text}\n  URL: {link}");
                    }
                }
            }

            if (results.Count == 0)
            {
                return $"No results found for '{query}'. Try rephrasing the query.";
            }

            return string.Join("\n\n", results);
        }
        catch (Exception ex)
        {
            logger.LogWarning(ex, "Search failed for query: {Query}", query);
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note with a title, content summary, and source URL. Use this to record important findings.")]
    public string SaveNote(
        [Description("Short title for the note")] string title,
        [Description("Content or summary of the finding")] string content,
        [Description("Source URL or reference")] string source)
    {
        noteStore.Add(title, content, source);
        logger.LogInformation("📝 Note saved: {Title}", title);
        return $"Note '{title}' saved successfully. Total notes: {noteStore.GetAll().Count}";
    }

    [Description("Retrieve all saved research notes collected so far.")]
    public string GetNotes()
    {
        var notes = noteStore.ToString();
        logger.LogInformation("📋 Retrieved {Count} notes", noteStore.GetAll().Count);
        return notes;
    }
}

